/// Token-less variant, safe for plaintext broadcast (mDNS). Only devices whose
/// keys are already paired can use it.
#[cfg(desktop)]
fn ssh_public_url(host: &str, served_name: &str) -> String {
    format!(
        "ssh://{host}:{LOCAL_SYNC_PORT}/{}",
